// ── Config ──
const SITE = 'https://spontana.app';
const FROM = 'Spontana <hello@spontana.app>'; // must be on a domain verified in Resend

// ── Helpers ──
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
// No auto-unsubscribe param: link scanners open URLs and would unsubscribe people
const prefsUrl = (token) => SITE + '/email-preferences?token=' + encodeURIComponent(token || '');
const eventUrl = (id) => SITE + '/event/' + encodeURIComponent(id);
const fmtDate = (d, lang) => d
  ? new Date(d + 'T12:00:00Z').toLocaleDateString(lang === 'en' ? 'en-GB' : 'sv-SE', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'Europe/Stockholm' })
  : '';
const when = (e, lang) => [fmtDate(e.date, lang), e.start_time].filter(Boolean).join(' · ');

const button = (href, label) =>
  '<a href="' + esc(href) + '" style="display:inline-block;background:#FDD53F;color:#0a0a0a;font-weight:700;text-decoration:none;padding:12px 22px;border-radius:6px;font-size:14px;letter-spacing:.04em;text-transform:uppercase">' + esc(label) + '</a>';

const eventCard = (e, lang) =>
  '<a href="' + esc(eventUrl(e.id)) + '" style="display:block;text-decoration:none;color:#F5F5F0;background:#141414;border:1px solid #2a2a2a;border-radius:8px;overflow:hidden;margin:0 0 14px">' +
    (e.img ? '<img src="' + esc(e.img) + '" alt="" width="520" style="display:block;width:100%;max-width:520px;height:auto;border:0">' : '') +
    '<div style="padding:14px 16px">' +
      '<div style="font-size:17px;font-weight:700;line-height:1.3;margin:0 0 4px">' + esc(e.name) + '</div>' +
      '<div style="font-size:13px;color:#888880">' + esc([when(e, lang), e.venue].filter(Boolean).join(' · ')) + '</div>' +
    '</div>' +
  '</a>';

const layout = ({ heading, body, footer }) =>
  '<!doctype html><html><body style="margin:0;padding:0;background:#0a0a0a">' +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#0a0a0a"><tr><td align="center" style="padding:32px 16px">' +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:520px;font-family:Inter,Helvetica,Arial,sans-serif;color:#F5F5F0">' +
    '<tr><td style="padding:0 0 28px;font-size:20px;font-weight:800;letter-spacing:.02em;color:#FDD53F">SPONTANA</td></tr>' +
    '<tr><td style="font-size:26px;font-weight:700;line-height:1.2;padding:0 0 14px">' + heading + '</td></tr>' +
    '<tr><td style="font-size:15px;line-height:1.6;color:#d0d0c8">' + body + '</td></tr>' +
    '<tr><td style="padding:32px 0 0;font-size:12px;line-height:1.5;color:#555550;border-top:1px solid #1e1e1e">' + footer + '</td></tr>' +
  '</table></td></tr></table></body></html>';

const link = (href, label) => '<a href="' + esc(href) + '" style="color:#888880">' + esc(label) + '</a>';

// ── Copy ──
const COPY = {
  sv: {
    welcome: () => ({
      subject: 'Du är inne.',
      heading: 'Du är inne.',
      body: '<p>Kontot är aktivt. Spara events du gillar så påminner vi dagen innan. Det är ungefär allt.</p>',
      cta: [SITE, 'Se vad som händer'],
    }),
    event_submitted: (e) => ({
      subject: 'Mottaget: ' + e.name,
      heading: 'Mottaget.',
      body: '<p>Vi har fått <strong>' + esc(e.name) + '</strong>. En människa tittar på det snart. Du får ett mejl när det är live.</p>',
      cta: null,
    }),
    event_approved: (e) => ({
      subject: e.name + ' är live.',
      heading: 'Det är live.',
      body: '<p><strong>' + esc(e.name) + '</strong> syns nu på Spontana. Dela länken, det hjälper.</p>',
      cta: [eventUrl(e.id), 'Visa eventet'],
    }),
    footer: 'Du får det här för att du har ett konto på Spontana.',
    prefs: 'E-postinställningar',
  },
  en: {
    welcome: () => ({
      subject: "You're in.",
      heading: "You're in.",
      body: "<p>Your account is live. Save events you like and we'll remind you the day before. That's roughly it.</p>",
      cta: [SITE, "See what's on"],
    }),
    event_submitted: (e) => ({
      subject: 'Got it: ' + e.name,
      heading: 'Got it.',
      body: "<p>We've received <strong>" + esc(e.name) + "</strong>. A human will look at it soon. You'll get an email when it's live.</p>",
      cta: null,
    }),
    event_approved: (e) => ({
      subject: e.name + ' is live.',
      heading: "It's live.",
      body: '<p><strong>' + esc(e.name) + '</strong> is now on Spontana. Share the link. It helps.</p>',
      cta: [eventUrl(e.id), 'View event'],
    }),
    footer: "You're getting this because you have a Spontana account.",
    prefs: 'Email settings',
  },
};

return $input.all().flatMap(({ json }) => {
  const p = json.body ?? json;
  const c = COPY[p.language === 'en' ? 'en' : 'sv'];
  if (!p.email || !c[p.kind]) return [];

  const m = c[p.kind](p.event || {});
  const card = p.event && p.kind === 'event_approved' ? eventCard(p.event, p.language) : '';
  const html = layout({
    heading: esc(m.heading),
    body: m.body + card + (m.cta ? '<p style="padding:12px 0 0">' + button(m.cta[0], m.cta[1]) + '</p>' : ''),
    footer: esc(c.footer) + (p.email_token ? ' ' + link(prefsUrl(p.email_token), c.prefs) : ''),
  });
  return [{ json: { from: FROM, to: p.email, subject: m.subject, html } }];
});
